1	package external
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"log/slog"
8		"os"
9		"os/exec"
10		"path/filepath"
11		"runtime"
12		"strings"
13		"time"
14	
15		"github.com/entireio/cli/cmd/entire/cli/agent"
16		"github.com/entireio/cli/cmd/entire/cli/agent/types"
17		"github.com/entireio/cli/cmd/entire/cli/logging"
18		"github.com/entireio/cli/cmd/entire/cli/settings"
19	)
20	
21	const (
22		binaryPrefix = "entire-agent-"
23		osWindows    = "windows"
24	)
25	
26	// discoveryTimeout caps the total time spent scanning $PATH for external agents.
27	const discoveryTimeout = 10 * time.Second
28	
29	var (
30		statExternalAgent     = os.Stat       //nolint:gochecknoglobals // narrow test seam for stat failures
31		lookPathExternalAgent = exec.LookPath //nolint:gochecknoglobals // narrow test seam for lookup failures
32	)
33	
34	// DiscoverAndRegister scans $PATH for executables matching "entire-agent-<name>",
35	// calls their "info" subcommand, and registers them in the agent registry.
36	// Binaries whose name conflicts with an already-registered agent are skipped.
37	// Errors during discovery are logged but do not prevent other agents from loading.
38	// Discovery is skipped when the external_agents setting is not enabled.
39	func DiscoverAndRegister(ctx context.Context) {
40		if !settings.IsExternalAgentsEnabled(ctx) {
41			logging.Debug(ctx, "external agent discovery disabled (external_agents not enabled in settings)")
42			return
43		}
44		discoverAndRegister(ctx)
45	}
46	
47	// DiscoverAndRegisterAlways is like DiscoverAndRegister but bypasses the
48	// external_agents settings check. Use this in interactive setup flows where
49	// the user explicitly chooses agents.
50	func DiscoverAndRegisterAlways(ctx context.Context) {
51		discoverAndRegister(ctx)
52	}
53	
54	// DiscoverAndRegisterNamedAlways discovers and registers only the external
55	// agent binary matching name. It bypasses the external_agents setting for
56	// explicit, one-invocation selections without executing unrelated plugins.
57	func DiscoverAndRegisterNamedAlways(ctx context.Context, name types.AgentName) error {
58		return discoverAndRegisterNamed(ctx, name, discoveryTimeout)
59	}
60	
61	// discoveryCanceled reports whether either the caller's context or the derived
62	// discovery-timeout context has been cancelled.
63	//
64	// Both must be consulted. A context closes its own Done channel *before* cancelling
65	// its children, so a goroutine that has just observed the caller's cancellation can
66	// run while the derived context still reports no error — and when the caller is not a
67	// standard context, propagation happens in a watcher goroutine, widening the window
68	// further. Checking only the derived context therefore lets a caller whose deadline
69	// expired mid-operation look like it is still live.
70	func discoveryCanceled(caller, derived context.Context) bool {
71		return caller.Err() != nil || derived.Err() != nil
72	}
73	
74	// discoveryCtxErr wraps whichever of the two contexts has been cancelled, preferring
75	// the caller's, and returns nil when neither has. op names the stage for the message.
76	// See discoveryCanceled for why the caller's context must be consulted too: missing it
77	// lets a caller whose deadline expired mid-lookup receive a nil error and a silently
78	// skipped agent instead of its context error.
79	func discoveryCtxErr(caller, derived context.Context, op string) error {
80		err := caller.Err()
81		if err == nil {
82			err = derived.Err()
83		}
84		if err == nil {
85			return nil
86		}
87		return fmt.Errorf("%s: %w", op, err)
88	}
89	
90	func discoverAndRegisterNamed(ctx context.Context, name types.AgentName, timeout time.Duration) error {
91		if name == "" {
92			return nil
93		}
94		if strings.ContainsAny(string(name), `/\`) {
95			return fmt.Errorf("invalid external agent name %q: contains path separators", name)
96		}
97		if _, err := agent.Get(name); err == nil {
98			return nil
99		}
100	
101		// `ctx` deliberately stays the CALLER's context; the derived timeout gets its own
102		// name. Shadowing `ctx` with the derived context is what caused the bug this
103		// function is guarding against, and it left the trap in place for the next edit.
104		discoveryCtx, cancel := context.WithTimeout(ctx, timeout)
105		defer cancel()
106		if err := discoveryCtxErr(ctx, discoveryCtx, fmt.Sprintf("discovering external agent %q", name)); err != nil {
107			return err
108		}
109	
110		binName := binaryPrefix + string(name)
111		binPath, err := lookPathExternalAgent(binName)
112		if ctxErr := discoveryCtxErr(ctx, discoveryCtx, fmt.Sprintf("looking up external agent %q binary %q", name, binName)); ctxErr != nil {
113			return ctxErr
114		}
115		if err != nil {
116			if errors.Is(err, exec.ErrNotFound) {
117				return nil
118			}
119			return fmt.Errorf("looking up external agent %q binary %q: %w", name, binName, err)
120		}
121		registered, err := registerExternalAgent(discoveryCtx, binPath, name)
122		if err != nil {
123			return err
124		}
125		if !registered {
126			return fmt.Errorf("external agent %q binary %q was found but could not be registered", name, binPath)
127		}
128		return nil
129	}
130	
131	// discoverAndRegister contains the shared scanning logic for external agent discovery.
132	func discoverAndRegister(ctx context.Context) {
133		// As above: `ctx` remains the caller's, the derived timeout is named.
134		discoveryCtx, cancel := context.WithTimeout(ctx, discoveryTimeout)
135		defer cancel()
136	
137		pathEnv := os.Getenv("PATH")
138		if pathEnv == "" {
139			return
140		}
141	
142		// Collect already-registered names to avoid conflicts.
143		registered := make(map[types.AgentName]bool)
144		for _, name := range agent.List() {
145			registered[name] = true
146		}
147	
148		seen := make(map[string]bool) // deduplicate binaries across PATH dirs
149		for _, dir := range filepath.SplitList(pathEnv) {
150			if discoveryCanceled(ctx, discoveryCtx) {
151				logging.Debug(ctx, "external agent discovery timed out")
152				return
153			}
154	
155			matches, err := filepath.Glob(filepath.Join(dir, binaryPrefix+"*"))
156			if err != nil {
157				continue // skip unreadable directories
158			}
159			for _, binPath := range matches {
160				if discoveryCanceled(ctx, discoveryCtx) {
161					logging.Debug(ctx, "external agent discovery timed out")
162					return
163				}
164	
165				name := filepath.Base(binPath)
166				if seen[name] {
167					continue
168				}
169				seen[name] = true
170	
171				// Strip Windows executable extensions (.exe, .bat) before deriving agent name.
172				// On Unix, binaries have no extension, so this is a no-op.
173				cleanName := StripExeExt(name)
174				agentName := types.AgentName(strings.TrimPrefix(cleanName, binaryPrefix))
175				if registered[agentName] {
176					logging.Debug(ctx, "skipping external agent (name conflict with built-in)",
177						slog.String("binary", name),
178						slog.String("agent", string(agentName)))
179					continue
180				}
181	
182				registeredAgent, err := registerExternalAgent(discoveryCtx, binPath, agentName)
183				if err != nil {
184					logging.Debug(ctx, "skipping external agent (registration failed)",
185						slog.String("binary", binPath),
186						slog.String("agent", string(agentName)),
187						slog.String("error", err.Error()))
188					continue
189				}
190				if registeredAgent {
191					registered[agentName] = true
192				}
193			}
194		}
195	}
196	
197	func registerExternalAgent(ctx context.Context, binPath string, name types.AgentName) (bool, error) {
198		finfo, err := statExternalAgent(binPath)
199		if err != nil {
200			if errors.Is(err, os.ErrNotExist) {
201				return false, nil
202			}
203			return false, fmt.Errorf("inspecting external agent %q binary %q: %w", name, binPath, err)
204		}
205		if finfo.IsDir() {
206			return false, nil
207		}
208		// Check executable bit (on Unix; Windows doesn't set execute bits).
209		if runtime.GOOS != osWindows && finfo.Mode()&0o111 == 0 {
210			return false, nil
211		}
212	
213		ea, err := New(ctx, binPath)
214		if err != nil {
215			if ctxErr := ctx.Err(); ctxErr != nil {
216				return false, fmt.Errorf("loading info for external agent %q from binary %q: %w: %w", name, binPath, ctxErr, err)
217			}
218			return false, fmt.Errorf("loading info for external agent %q from binary %q: %w", name, binPath, err)
219		}
220	
221		wrapped, err := Wrap(ea)
222		if err != nil {
223			return false, fmt.Errorf("wrapping external agent %q from binary %q: %w", name, binPath, err)
224		}
225		agent.Register(name, func() agent.Agent {
226			return wrapped
227		})
228	
229		logging.Debug(ctx, "registered external agent",
230			slog.String("name", string(name)),
231			slog.String("type", string(ea.Type())),
232			slog.String("binary", binPath))
233		return true, nil
234	}
235	
236	// StripExeExt removes Windows executable extensions (.exe, .bat, .cmd, .com)
237	// from a file name so that the derived name matches on all platforms. On Unix
238	// this is effectively a no-op because binaries have no extension.
239	//
240	// .com is included because Windows PATHEXT defaults to ".COM;.EXE;.BAT;.CMD;…",
241	// so exec.LookPath can resolve a `.com` next to a `.exe`. Without stripping
242	// it, a managed-plugin or agent-binary installer would treat foo.exe and
243	// foo.com as distinct names while PATHEXT silently picks one.
244	func StripExeExt(name string) string {
245		switch strings.ToLower(filepath.Ext(name)) {
246		case ".exe", ".bat", ".cmd", ".com":
247			return strings.TrimSuffix(name, filepath.Ext(name))
248		}
249		return name
250	}
