var (
	statExternalAgent     = os.Stat       //nolint:gochecknoglobals // narrow test seam for stat failures
	lookPathExternalAgent = exec.LookPath //nolint:gochecknoglobals // narrow test seam for lookup failures
)

// DiscoverAndRegister scans $PATH for executables matching "entire-agent-<name>",
// calls their "info" subcommand, and registers them in the agent registry.
// Binaries whose name conflicts with an already-registered agent are skipped.
// Errors during discovery are logged but do not prevent other agents from loading.
// Discovery is skipped when the external_agents setting is not enabled.
func DiscoverAndRegister(ctx context.Context) {
	if !settings.IsExternalAgentsEnabled(ctx) {
		logging.Debug(ctx, "external agent discovery disabled (external_agents not enabled in settings)")
		return
	}
	discoverAndRegister(ctx)
}

// DiscoverAndRegisterAlways is like DiscoverAndRegister but bypasses the
// external_agents settings check. Use this in interactive setup flows where
// the user explicitly chooses agents.
func DiscoverAndRegisterAlways(ctx context.Context) {
	discoverAndRegister(ctx)
}

// DiscoverAndRegisterNamedAlways discovers and registers only the external
// agent binary matching name. It bypasses the external_agents setting for
// explicit, one-invocation selections without executing unrelated plugins.
func DiscoverAndRegisterNamedAlways(ctx context.Context, name types.AgentName) error {
	return discoverAndRegisterNamed(ctx, name, discoveryTimeout)
}

// discoveryCanceled reports whether either the caller's context or the derived
// discovery-timeout context has been cancelled.
//
// Both must be consulted. A context closes its own Done channel *before* cancelling
// its children, so a goroutine that has just observed the caller's cancellation can
// run while the derived context still reports no error — and when the caller is not a
// standard context, propagation happens in a watcher goroutine, widening the window
// further. Checking only the derived context therefore lets a caller whose deadline
// expired mid-operation look like it is still live.
func discoveryCanceled(caller, derived context.Context) bool {
	return caller.Err() != nil || derived.Err() != nil
}

// discoveryCtxErr wraps whichever of the two contexts has been cancelled, preferring
// the caller's, and returns nil when neither has. op names the stage for the message.
// See discoveryCanceled for why the caller's context must be consulted too: missing it
// lets a caller whose deadline expired mid-lookup receive a nil error and a silently
// skipped agent instead of its context error.
func discoveryCtxErr(caller, derived context.Context, op string) error {
	err := caller.Err()
	if err == nil {
		err = derived.Err()
	}
	if err == nil {
		return nil
	}
	return fmt.Errorf("%s: %w", op, err)
}

func discoverAndRegisterNamed(ctx context.Context, name types.AgentName, timeout time.Duration) error {
	if name == "" {
		return nil
	}
	if strings.ContainsAny(string(name), `/\`) {
		return fmt.Errorf("invalid external agent name %q: contains path separators", name)
	}
	if _, err := agent.Get(name); err == nil {
		return nil
	}

	// `ctx` deliberately stays the CALLER's context; the derived timeout gets its own
	// name. Shadowing `ctx` with the derived context is what caused the bug this
	// function is guarding against, and it left the trap in place for the next edit.
	discoveryCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	if err := discoveryCtxErr(ctx, discoveryCtx, fmt.Sprintf("discovering external agent %q", name)); err != nil {
		return err
	}

	binName := binaryPrefix + string(name)
	binPath, err := lookPathExternalAgent(binName)
	if ctxErr := discoveryCtxErr(ctx, discoveryCtx, fmt.Sprintf("looking up external agent %q binary %q", name, binName)); ctxErr != nil {
		return ctxErr
	}
	if err != nil {
		if errors.Is(err, exec.ErrNotFound) {
			return nil
		}
		return fmt.Errorf("looking up external agent %q binary %q: %w", name, binName, err)
	}
	registered, err := registerExternalAgent(discoveryCtx, binPath, name)
	if err != nil {
		return err
	}
	if !registered {
		return fmt.Errorf("external agent %q binary %q was found but could not be registered", name, binPath)
	}
	return nil
}

// discoverAndRegister contains the shared scanning logic for external agent discovery.
func discoverAndRegister(ctx context.Context) {
	// As above: `ctx` remains the caller's, the derived timeout is named.
	discoveryCtx, cancel := context.WithTimeout(ctx, discoveryTimeout)
	defer cancel()

	pathEnv := os.Getenv("PATH")
	if pathEnv == "" {
		return
	}

	// Collect already-registered names to avoid conflicts.
	registered := make(map[types.AgentName]bool)
	for _, name := range agent.List() {
		registered[name] = true
	}

	seen := make(map[string]bool) // deduplicate binaries across PATH dirs
	for _, dir := range filepath.SplitList(pathEnv) {
		if discoveryCanceled(ctx, discoveryCtx) {
			logging.Debug(ctx, "external agent discovery timed out")
			return
		}

		matches, err := filepath.Glob(filepath.Join(dir, binaryPrefix+"*"))
		if err != nil {
			continue // skip unreadable directories
		}
		for _, binPath := range matches {
			if discoveryCanceled(ctx, discoveryCtx) {
				logging.Debug(ctx, "external agent discovery timed out")
				return
			}

			name := filepath.Base(binPath)
			if seen[name] {
				continue
			}
			seen[name] = true

			// Strip Windows executable extensions (.exe, .bat) before deriving agent name.
			// On Unix, binaries have no extension, so this is a no-op.
			cleanName := StripExeExt(name)
			agentName := types.AgentName(strings.TrimPrefix(cleanName, binaryPrefix))
			if registered[agentName] {
				logging.Debug(ctx, "skipping external agent (name conflict with built-in)",
					slog.String("binary", name),
					slog.String("agent", string(agentName)))
				continue
			}

			registeredAgent, err := registerExternalAgent(discoveryCtx, binPath, agentName)
			if err != nil {
				logging.Debug(ctx, "skipping external agent (registration failed)",
					slog.String("binary", binPath),
					slog.String("agent", string(agentName)),
					slog.String("error", err.Error()))
				continue
			}
			if registeredAgent {
				registered[agentName] = true
			}
		}
	}
}

func registerExternalAgent(ctx context.Context, binPath string, name types.AgentName) (bool, error) {
	finfo, err := statExternalAgent(binPath)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return false, nil
		}
		return false, fmt.Errorf("inspecting external agent %q binary %q: %w", name, binPath, err)
	}
	if finfo.IsDir() {
		return false, nil
	}
	// Check executable bit (on Unix; Windows doesn't set execute bits).
	if runtime.GOOS != osWindows && finfo.Mode()&0o111 == 0 {
		return false, nil
	}

	ea, err := New(ctx, binPath)
	if err != nil {
		if ctxErr := ctx.Err(); ctxErr != nil {
			return false, fmt.Errorf("loading info for external agent %q from binary %q: %w: %w", name, binPath, ctxErr, err)
		}
		return false, fmt.Errorf("loading info for external agent %q from binary %q: %w", name, binPath, err)
	}

	wrapped, err := Wrap(ea)
	if err != nil {
		return false, fmt.Errorf("wrapping external agent %q from binary %q: %w", name, binPath, err)
	}
	agent.Register(name, func() agent.Agent {
		return wrapped
	})

	logging.Debug(ctx, "registered external agent",
		slog.String("name", string(name)),
		slog.String("type", string(ea.Type())),
		slog.String("binary", binPath))
	return true, nil
}

// StripExeExt removes Windows executable extensions (.exe, .bat, .cmd, .com)
// from a file name so that the derived name matches on all platforms. On Unix
// this is effectively a no-op because binaries have no extension.
//
// .com is included because Windows PATHEXT defaults to ".COM;.EXE;.BAT;.CMD;…",
// so exec.LookPath can resolve a `.com` next to a `.exe`. Without stripping
// it, a managed-plugin or agent-binary installer would treat foo.exe and
// foo.com as distinct names while PATHEXT silently picks one.
func StripExeExt(name string) string {
	switch strings.ToLower(filepath.Ext(name)) {
	case ".exe", ".bat", ".cmd", ".com":
		return strings.TrimSuffix(name, filepath.Ext(name))
	}
	return name
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/external"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/settings"
	"github.com/spf13/cobra"
)

// newAgentGroupCmd builds `entire agent`. Replaces `entire configure`.
func newAgentGroupCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "agent",
		Short: "Manage agent integrations (add, remove, list)",
		Long: `Manage agent integrations in this repository.

Commands:
  list     Show installed and available agents
  add      Install hooks for an agent
  remove   Uninstall hooks for an agent

Examples:
  entire agent
  entire agent list
  entire agent add claude-code
  entire agent remove claude-code`,
		PersistentPreRunE: func(cmd *cobra.Command, _ []string) error {
			if _, err := paths.WorktreeRoot(cmd.Context()); err != nil {
				return errors.New("not a git repository")
			}
			return nil
		},
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runAgentMenu(cmd.Context(), cmd.OutOrStdout())
		},
	}

	cmd.AddCommand(newAgentListCmd())
	cmd.AddCommand(newAgentAddCmd())
	cmd.AddCommand(newAgentRemoveCmd())
	return cmd
}

func runAgentMenu(ctx context.Context, w io.Writer) error {
	opts := EnableOptions{Telemetry: true}
	if settings.IsSetUpAny(ctx) {
		return runManageAgents(ctx, w, opts, nil)
	}
	return runSetupFlow(ctx, w, opts)
}

func newAgentListCmd() *cobra.Command {
	var externalOnly bool
	cmd := &cobra.Command{
		Use:   "list",
		Short: "List built-in agents (use --external to list external plugins on your PATH)",
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runAgentList(cmd.Context(), cmd.OutOrStdout(), externalOnly)
		},
	}
	cmd.Flags().BoolVar(&externalOnly, "external", false,
		"List external agent plugins found on your PATH instead of built-in agents")
	return cmd
}

func runAgentList(ctx context.Context, w io.Writer, externalOnly bool) error {
	// --external is the explicit opt-in to the costly path: register external
	// plugins from $PATH so they list through the same rendering as built-ins
	// (real names, capabilities, test-only filtering). The default path never
	// discovers, so it stays fast regardless of how many plugins are on $PATH.
	if externalOnly {
		external.DiscoverAndRegisterAlways(ctx)
	}

	hasSomeInstalled := false
	fmt.Fprintln(w, "Agents:")
	for _, name := range agent.List() {
		ag, err := agent.Get(name)
		if err != nil {
			logging.Debug(ctx, "agent registered but unresolvable, skipping",
				slog.String("agent", string(name)), slog.String("error", err.Error()))
			continue
		}
		if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
			continue
		}
		// Default lists built-in agents; --external lists external plugins.
		if external.IsExternal(ag) != externalOnly {
			continue
		}
		installed := false
		if hs, ok := agent.AsHookSupport(ag); ok && hs.AreHooksInstalled(ctx) {
			installed = true
			hasSomeInstalled = true
		}
		marker := "  "
		if installed {
			marker = "✓ "
		}
		fmt.Fprintf(w, "  %s%s\n", marker, name)
	}

	if !hasSomeInstalled {
		fmt.Fprintln(w, "\nNo agents installed. Use 'entire agent add <name>' to install hooks.")
	}
	if !externalOnly {
		fmt.Fprintln(w, "\nRun 'entire agent list --external' to list external agent plugins on your PATH.")
	}
	return nil
}

func newAgentAddCmd() *cobra.Command {
	var localDev bool
	var forceHooks bool
	var searchSkill bool
	var agentHelpSkill bool

	cmd := &cobra.Command{
		Use:   "add <agent-name>",
		Short: "Install hooks for an agent",
		Long: `Install hooks for the specified agent in this repository.

Examples:
  entire agent add claude-code
  entire agent add gemini`,
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			name := args[0]
			// Resolve the named external agent plugin so `add` works like
			// `entire enable --agent <name>`. Targeting the single name (rather
			// than a full $PATH scan) avoids executing every unrelated
			// entire-agent-* binary and surfaces a real load error instead of a
			// generic "unknown agent". Bypasses the setting gate because this
			// command is itself the explicit opt-in.
			if err := external.DiscoverAndRegisterNamedAlways(cmd.Context(), types.AgentName(name)); err != nil {
				cmd.SilenceUsage = true
				return fmt.Errorf("loading external agent %q: %w", name, err)
			}
			ag, err := agent.Get(types.AgentName(name))
			if err != nil {
				printWrongAgentError(cmd.OutOrStdout(), name)
				return NewSilentError(errors.New("wrong agent name"))
			}
			opts := EnableOptions{
				LocalDev:       localDev,
				ForceHooks:     forceHooks,
				SearchSkill:    searchSkill,
				AgentHelpSkill: agentHelpSkill,
				Telemetry:      true,
			}
			return setupAgentHooksNonInteractive(cmd.Context(), cmd.OutOrStdout(), ag, opts)
		},
	}

	cmd.Flags().BoolVar(&localDev, "local-dev", false, "Install hooks in local-dev mode")
	cmd.Flags().BoolVar(&forceHooks, "force", false, "Reinstall hooks even if already present")
	cmd.Flags().BoolVar(&searchSkill, flagSearchSkill, false, "Install the optional Entire search skill")
	cmd.Flags().BoolVar(&agentHelpSkill, flagAgentHelpSkill, false, "Install the stable Entire agent-help skill (points agents at `entire agent-help`)")
	return cmd
}

func newAgentRemoveCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "remove <agent-name>",
		Short: "Uninstall hooks for an agent",
		Long: `Uninstall hooks for the specified agent in this repository.

Examples:
  entire agent remove claude-code`,
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			// Resolve the named external agent plugin so `remove` can find it,
			// executing only that binary rather than scanning all of $PATH.
			if err := external.DiscoverAndRegisterNamedAlways(cmd.Context(), types.AgentName(args[0])); err != nil {
				cmd.SilenceUsage = true
				return fmt.Errorf("loading external agent %q: %w", args[0], err)
			}
			return runRemoveAgent(cmd.Context(), cmd.OutOrStdout(), args[0])
		},
	}
}

package agent

import (
	"context"
	"fmt"
	"maps"
	"path/filepath"
	"runtime"
	"slices"
	"strings"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

var (
	registryMu sync.RWMutex
	registry   = make(map[types.AgentName]Factory)
)

// Factory creates a new agent instance
type Factory func() Agent

// Register adds an agent factory to the registry.
// Called from init() in each agent implementation.
func Register(name types.AgentName, factory Factory) {
	registryMu.Lock()
	defer registryMu.Unlock()
	registry[name] = factory
}

// SnapshotForTesting captures the registry's current contents and returns a
// function that restores it to exactly that state.
//
// Tests that trigger agent registration as a side effect — external-agent
// discovery via runAgentList, for example — must defer or t.Cleanup the
// returned restore. Otherwise mock agents backed by t.TempDir binaries leak
// into the process-global registry and corrupt later tests in the package:
// GetAgentsWithHooksInstalled would exec their now-deleted binaries, and only
// TempDir cleanup ordering keeps that from mis-reporting installed agents.
//
// Both capture and restore hold registryMu, so it is safe against concurrent
// registry readers.
func SnapshotForTesting() func() {
	registryMu.Lock()
	defer registryMu.Unlock()
	snapshot := make(map[types.AgentName]Factory, len(registry))
	maps.Copy(snapshot, registry)
	return func() {
		registryMu.Lock()
		defer registryMu.Unlock()
		registry = snapshot
	}
}

// Get retrieves an agent by name.
//

func Get(name types.AgentName) (Agent, error) {
	registryMu.RLock()
	defer registryMu.RUnlock()

	factory, ok := registry[name]
	if !ok {
		return nil, fmt.Errorf("unknown agent: %s (available: %v)", name, List())
	}
	return factory(), nil
}

// List returns all registered agent names in sorted order.
func List() []types.AgentName {
	registryMu.RLock()
	defer registryMu.RUnlock()

	names := make([]types.AgentName, 0, len(registry))
	for name := range registry {
		names = append(names, name)
	}
	slices.Sort(names)
	return names
}

// StringList returns user-facing agent names, excluding test-only agents.
func StringList() []string {
	registryMu.RLock()
	defer registryMu.RUnlock()

	names := make([]string, 0, len(registry))
	for name, factory := range registry {
		if to, ok := factory().(TestOnly); ok && to.IsTestOnly() {
			continue
		}
		names = append(names, string(name))
	}
	slices.Sort(names)
	return names
}

// DetectAll returns all agents whose DetectPresence reports true.
// Agents are checked in sorted name order (via List()) for deterministic results.

